// Ymatch — Over ons · Het team (full roster grid).
//
// Vijftien mensen, met foto/initialen, rol, en directe contact-iconen
// (LinkedIn, e-mail, telefoon). Drie van de vijftien hebben een echte
// portret-foto (Jan, Lisa, Sander); de rest krijgt voorlopig een
// initialen-avatar — vervang `photo:` zodra de echte foto's er zijn.

function TeamMemberCard({ m }) {
  return (
    <article style={{
      background: "var(--card)", border: "1px solid var(--line)", borderRadius: "var(--r)",
      overflow: "hidden", boxShadow: "var(--shadow-sm)", position: "relative",
      display: "flex", flexDirection: "column",
      transition: "transform .18s, box-shadow .18s, border-color .18s",
    }}
    onMouseEnter={(e) => {
      e.currentTarget.style.transform = "translateY(-3px)";
      e.currentTarget.style.boxShadow = "var(--shadow-lg)";
      e.currentTarget.style.borderColor = "rgba(233,78,27,.25)";
    }}
    onMouseLeave={(e) => {
      e.currentTarget.style.transform = "none";
      e.currentTarget.style.boxShadow = "var(--shadow-sm)";
      e.currentTarget.style.borderColor = "var(--line)";
    }}>
      <div style={{ position: "absolute", top: 0, left: 0, right: 0, height: "3px", background: m.tone, zIndex: 2 }} />

      {/* Photo or initials avatar */}
      <div style={{ aspectRatio: "1 / 1", background: m.photo ? "var(--bg-2)" : m.tone, position: "relative", overflow: "hidden" }}>
        {m.photo ? (
          <img src={m.photo} alt={m.name} style={{ display: "block", width: "100%", height: "100%", objectFit: "cover", objectPosition: "center 20%" }} />
        ) : (
          <div style={{
            position: "absolute", inset: 0, display: "flex", alignItems: "center", justifyContent: "center",
            color: "#fff", fontFamily: "var(--font-hand)", fontWeight: 700, fontSize: "80px", lineHeight: 1,
          }}>
            {m.initials}
          </div>
        )}
        {m.lead && (
          <span style={{
            position: "absolute", top: "12px", left: "12px",
            background: "var(--ink)", color: "#fff",
            fontFamily: "var(--font-mono)", fontSize: "9px", fontWeight: 700, letterSpacing: ".08em", textTransform: "uppercase",
            padding: "5px 9px", borderRadius: "var(--r-xs)",
          }}>{m.lead}</span>
        )}
      </div>

      {/* Body */}
      <div style={{ padding: "16px 18px 14px", display: "flex", flexDirection: "column", gap: "4px" }}>
        <h3 style={{ fontFamily: "var(--font-display)", fontWeight: 800, fontSize: "17px", letterSpacing: "-.02em", margin: 0, color: "var(--ink)", lineHeight: 1.15 }}>
          {m.name}
        </h3>
        <div style={{ fontFamily: "var(--font-mono)", fontSize: "10px", fontWeight: 700, letterSpacing: ".06em", textTransform: "uppercase", color: "var(--muted)", minHeight: "14px" }}>
          {m.role}
        </div>
        {m.tagline && (
          <div style={{ fontFamily: "var(--font-hand)", fontSize: "15px", color: "var(--blue)", lineHeight: 1, marginTop: "2px" }}>
            {m.tagline}
          </div>
        )}
      </div>

      {/* Contact icon row */}
      <div style={{ marginTop: "auto", padding: "12px 16px 14px", borderTop: "1px solid var(--line)", display: "flex", gap: "8px" }}>
        <TeamIconLink href={`mailto:${m.email}`} title={m.email} aria-label={`Mail ${m.name}`}>
          <window.Icons.mail size={15} stroke="currentColor" />
        </TeamIconLink>
        <TeamIconLink href={`tel:${(m.tel || "").replace(/\s/g, "")}`} title={m.tel} aria-label={`Bel ${m.name}`}>
          <window.Icons.phone size={15} stroke="currentColor" />
        </TeamIconLink>
        <TeamIconLink href={m.linkedin} target="_blank" rel="noopener" title="LinkedIn" aria-label={`LinkedIn ${m.name}`}>
          <svg width="14" height="14" viewBox="0 0 24 24" fill="currentColor"><path d="M19 3a2 2 0 0 1 2 2v14a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2h14zM8.34 18.34V9.67H5.67v8.67h2.67zM7 8.5a1.55 1.55 0 1 0 0-3.1 1.55 1.55 0 0 0 0 3.1zm11.34 9.84v-4.74c0-2.47-1.33-3.62-3.1-3.62a2.67 2.67 0 0 0-2.42 1.33h-.04V9.67h-2.55c.03.74 0 8.67 0 8.67h2.55v-4.84c0-.23.02-.46.08-.62.18-.46.6-.94 1.3-.94.92 0 1.28.7 1.28 1.72v4.68h2.55z"/></svg>
        </TeamIconLink>
        <span style={{ marginLeft: "auto", display: "inline-flex", alignItems: "center", fontFamily: "var(--font-mono)", fontSize: "9px", fontWeight: 700, letterSpacing: ".06em", textTransform: "uppercase", color: "var(--subtle)" }}>
          {m.team}
        </span>
      </div>
    </article>
  );
}

function TeamIconLink({ children, ...rest }) {
  const [hover, setHover] = React.useState(false);
  return (
    <a {...rest} style={{
      display: "inline-flex", alignItems: "center", justifyContent: "center",
      width: "32px", height: "32px", borderRadius: "var(--r-xs)",
      background: hover ? "var(--orange-tint)" : "var(--bg-2)",
      color: hover ? "var(--orange)" : "var(--ink)",
      textDecoration: "none", transition: "all .14s",
    }}
    onMouseEnter={() => setHover(true)}
    onMouseLeave={() => setHover(false)}>
      {children}
    </a>
  );
}

